use vstd::prelude::*;

verus! {
    fn min_array(a: &Vec<i32>) -> (result: i32)
        requires
            a.len() > 0,
        ensures
            // the result really occurs in the array
            exists i: int :: 
                0 <= i && i < a.len() as int &&
                result == a@.index(i),
            // the result is ≤ every element
            forall i: int ::
                0 <= i && i < a.len() as int ==>
                result <= a@.index(i)
    {
        // initialize min_val to the first element
        let mut min_val: i32 = a[0];
        let mut idx: usize = 1;
        let n = a.len();

        // scan from idx = 1 up to n
        while idx < n
            invariant
                // 1 ≤ idx ≤ n
                1 <= idx && idx <= n,
                // min_val is ≤ every element in the visited prefix a[0..idx)
                forall i: int ::
                    0 <= i && i < idx as int ==>
                    min_val <= a@.index(i),
                // and it actually equals at least one element in that prefix
                exists j: int ::
                    0 <= j && j < idx as int &&
                    a@.index(j) == min_val,
            decreases
                n - idx
        {
            let x: i32 = a[idx];
            if x < min_val {
                min_val = x;
            }
            idx = idx + 1;
        }

        // when idx == n, the invariants say min_val is the min of the whole array
        result = min_val;
    }
}

